#!/usr/bin/env node
// Skills codegen (handoff 03 step 3): inlines every skills/*/SKILL.md with its sha256 into src/skills.generated.ts so
// Convex actions (which can't read package files at runtime) get the exact skill text. The text is never edited here.
// `--check` exits 1 when the generated file is out of date (CI and the package test).
import { createHash } from "node:crypto";
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const out = join(root, "src", "skills.generated.ts");

export function render() {
	const ids = readdirSync(join(root, "skills"), { withFileTypes: true })
		.filter((d) => d.isDirectory() && existsSync(join(root, "skills", d.name, "SKILL.md")))
		.map((d) => d.name)
		.sort();
	const rows = ids.map((id) => {
		const text = readFileSync(join(root, "skills", id, "SKILL.md"), "utf8").replace(/\r\n/g, "\n");
		const sha256 = createHash("sha256").update(text).digest("hex");
		return `  ${JSON.stringify(id)}: { sha256: ${JSON.stringify(sha256)}, text: ${JSON.stringify(text)} },`;
	});
	return [
		"// GENERATED by scripts/build-skills.mjs from skills/*/SKILL.md. Do not edit; run `pnpm build:skills`.",
		"export interface ISkillText {",
		"  sha256: string;",
		"  text: string;",
		"}",
		"",
		"export const SKILLS: Readonly<Record<string, ISkillText>> = {",
		...rows,
		"};",
		"",
	].join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
	const next = render();
	const current = existsSync(out) ? readFileSync(out, "utf8").replace(/\r\n/g, "\n") : "";
	if (process.argv.includes("--check")) {
		if (current !== next) {
			console.error("skills.generated.ts is out of date: run `pnpm --filter @studio/seo-harness build:skills`");
			process.exit(1);
		}
		console.log("skills.generated.ts: ok");
	} else {
		writeFileSync(out, next);
		console.log(`wrote ${out}`);
	}
}
